/**
 * The single content adapter. Components import typed, token-resolved
 * objects from here and never reach into the raw JSON.
 *
 * Sources of truth:
 *  - content/site.json            copy for every section, ledger, sources (S1..S70)
 *  - src/data/sim.json            {{sim.*}} token values (regenerated by the simulation step)
 *  - src/data/demo.json           precomputed simulation outputs (feed, SHAP, counterfactuals)
 *  - content/claims.verified.json only for fact-check metadata (notes, evidence, "changed")
 *
 * Every {{sim.key}} in site.json is replaced with sim.json[key].display at
 * build time. A missing key throws and fails the build.
 */
import siteRaw from "../../content/site.json";
import verifiedRaw from "../../content/claims.verified.json";
import simRaw from "../data/sim.json";
import demoRaw from "../data/demo.json";

