/* ------------------------------------------------------------------ */
/* Token resolution                                                    */
/* ------------------------------------------------------------------ */

export const simTokens = simRaw as unknown as Record<string, SimToken>;

const TOKEN_RE = /\{\{\s*sim\.([A-Za-z0-9_]+)\s*\}\}/g;

/** Replace every {{sim.key}} with simTokens[key].display. Throws on a missing key. */
export function resolveTokens(str: string): string {
  return str.replace(TOKEN_RE, (_m, key: string) => {
    const tok = simTokens[key];
    if (!tok) throw new Error(`content.ts: unknown sim token "{{sim.${key}}}" in: ${str.slice(0, 120)}`);
    return tok.display;
  });
}

/** Deep-resolve tokens in every string of a JSON-like value. */
function resolveDeep<T>(value: T): T {
  if (typeof value === "string") return resolveTokens(value) as T;
  if (Array.isArray(value)) return value.map((v) => resolveDeep(v)) as T;
  if (value && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value)) out[k] = resolveDeep(v);
    return out as T;
  }
  return value;
}

/** A sim token's display string (for numbers built into instrument copy). */
export function simDisplay(key: string): string {
  const tok = simTokens[key];
  if (!tok) throw new Error(`content.ts: unknown sim token "${key}"`);
  return tok.display;
}
/** A sim token's raw value. */
export function simValue<T extends SimToken["value"] = SimToken["value"]>(key: string): T {
  const tok = simTokens[key];
  if (!tok) throw new Error(`content.ts: unknown sim token "${key}"`);
  return tok.value as T;
}

