const rawSite = siteRaw as unknown as {
  meta: { title: string; subtitle: string; author: string; affil: string; asOf: string; description: string };
  sections: Array<{ id: string; kind: string }>;
  ledger: LedgerRow[];
  sources: Record<SourceId, Source>;
  simQualitative: { where: string; phrase: string; holds_if: string }[];
};

export const meta = rawSite.meta;
export const sources: Record<SourceId, Source> = rawSite.sources;
export const simQualitative = rawSite.simQualitative;

const resolvedSections = resolveDeep(rawSite.sections);

function section<T>(id: string): T {
  const s = resolvedSections.find((x) => x.id === id);
  if (!s) throw new Error(`content.ts: section "${id}" missing from site.json`);
  return s as unknown as T;
}

