/* ---- Policy ---- */

/**
 * Fill vs ring on the policy spectrum, mapped by hand from each measure's
 * verified status text (site.json, Oct 18 2026). Review if status copy changes.
 * Rule (design.md 8.1): "in_effect" = in effect or decided; "pending" = pending,
 * proposed, or under challenge.
 */
const STATUS_STATE: Record<string, Measure["statusState"]> = {
  au: "in_effect", // In force since Dec 10, 2025
  bans: "pending", // Mixed: in force, pending, struck down
  ny: "pending", // Takes effect Jan 25, 2027
  ca: "pending", // Partly in effect; in litigation
  uk: "in_effect", // In force since Jul 25, 2025
  dsa: "in_effect", // In force
  "dsa-risk": "in_effect", // In force; vetting slow
  "dsa-minors": "in_effect", // Guidelines adopted
  aiact: "in_effect", // In force; untested on feeds
  kosa: "pending", // Pending in the Senate
  kgm: "pending", // Verdict; on appeal (under challenge)
  nm: "in_effect", // Judgment entered; appeal only planned
};

const lawRaw = section<LawSectionRaw>("act-law");
export const law: LawSection = {
  ...lawRaw,
  measures: lawRaw.measures.map((m) => {
    const statusState = STATUS_STATE[m.id];
    if (!statusState) throw new Error(`content.ts: no statusState mapped for measure "${m.id}"`);
    return { ...m, statusState, requiresExplanation: m.explain.level !== "none" };
  }),
};

/** Band order on the policy spectrum, left ("doesn't touch it") to right ("changes it"). design.md 8.1 */
export const MEASURE_BANDS: MeasureType[] = ["Access", "Liability", "Transparency", "Design"];

/** Measures grouped by band, each band sorted by jurisdiction name. */
export function measuresByBand(): { band: MeasureType; measures: Measure[] }[] {
  return MEASURE_BANDS.map((band) => ({
    band,
    measures: law.measures
      .filter((m) => m.type === band)
      .sort((a, b) => a.juris.localeCompare(b.juris) || a.name.localeCompare(b.name)),
  }));
}

/* ---- Technical ---- */

/** Parse a test `score` ("Pass / Partial", "Fail (platform-style)") into glyphs, in order. */
export function parseScore(score: string): Glyph[] {
  const out: Glyph[] = [];
  for (const m of score.toLowerCase().matchAll(/\b(pass|partial|fail)\b/g)) out.push(m[1] as Glyph);
  if (!out.length) throw new Error(`content.ts: cannot parse test score "${score}"`);
  return out;
}

const modelRaw = section<ModelSectionRaw>("act-model");
export const model: ModelSection = {
  ...modelRaw,
  tests: modelRaw.tests.map((t) => ({ ...t, glyphs: parseScore(t.score) })),
};

/** Counts of glyph instances across the five tests, for "3 pass, 1 partial, 2 fail across 5 tests". */
export function scorecardSummary(): { pass: number; partial: number; fail: number; tests: number } {
  const c = { pass: 0, partial: 0, fail: 0, tests: model.tests.length };
  for (const t of model.tests) for (const g of t.glyphs) c[g]++;
  return c;
}

