/* ------------------------------------------------------------------ */
/* Sentence splitting (thesis display line, conclusion line)           */
/* ------------------------------------------------------------------ */

const ABBREV = /(?:\b(?:U\.S|U\.K|Dr|Mr|Mrs|Ms|St|vs|e\.g|i\.e|etc|Oct|Sept|Jan|Feb|Aug|Dec|Nov|No))\.$/;

/** Split text into sentences without changing any characters (joining with " " restores it). */
export function splitSentences(text: string): string[] {
  const parts: string[] = [];
  let start = 0;
  const re = /[.!?]["”')\]]?\s+(?=["“(]?[A-Z0-9])/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(text))) {
    const end = m.index + m[0].trimEnd().length;
    const candidate = text.slice(start, end);
    if (ABBREV.test(candidate)) continue;
    parts.push(candidate);
    start = m.index + m[0].length;
  }
  parts.push(text.slice(start));
  return parts.filter(Boolean);
}

/* ------------------------------------------------------------------ */
/* Sources and citations                                               */
/* ------------------------------------------------------------------ */

/** The project's own simulation. Numbers sourced to it carry the Simulated marker. */
export const SIM_SOURCE: SourceId = "S28";

export const isSimSource = (id: SourceId) => id === SIM_SOURCE;
/** True if a span is (partly) a simulation result. */
export const isSimulated = (text: Pick<Text, "s">) => text.s.includes(SIM_SOURCE);

export function getSource(id: SourceId): Source {
  const src = sources[id];
  if (!src) throw new Error(`content.ts: unknown source "${id}"`);
  return src;
}
/** "S29" -> 29 (what the citation marker shows). */
export const sourceNumber = (id: SourceId) => Number(id.replace(/^S/, ""));
/** Anchor id of a source in the sources list: "src-S29". */
export const sourceAnchor = (id: SourceId) => `src-${id}`;
/** Anchor id of a ledger row: "claim-12". */
export const claimAnchor = (id: number) => `claim-${id}`;
/** "https://www.bbc.co.uk/news/x" -> "bbc.co.uk" */
export function sourceDomain(url: string | null): string | null {
  if (!url) return null;
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return null;
  }
}

/** All sources in numeric order, for the numbered source list. */
export const sourceList = Object.entries(sources)
  .map(([id, s]) => ({ id, n: sourceNumber(id), ...s }))
  .sort((a, b) => a.n - b.n);

/* ------------------------------------------------------------------ */
/* Ledger and fact-check status                                        */
/* ------------------------------------------------------------------ */

interface FactcheckEntry {
  verdict: string;
  changed: boolean;
  before: string | null;
  after: string | null;
  evidence_urls: string[];
  note: string;
  where: string;
}
const factcheckRaw = (verifiedRaw as unknown as { factcheck: Record<string, FactcheckEntry> }).factcheck;
export const factcheckMeta = factcheckRaw._meta as unknown as {
  checked_on: string;
  method: string;
  pending_simulation: number[];
};

export const ledger: LedgerRow[] = rawSite.ledger.map((r) => ({ ...r, text: resolveTokens(r.text) }));
const ledgerById = new Map(ledger.map((r) => [r.id, r]));

export function getClaim(id: number): LedgerRow {
  const r = ledgerById.get(id);
  if (!r) throw new Error(`content.ts: unknown ledger claim ${id}`);
  return r;
}

export const VERDICT_LABEL: Record<LedgerVerdict, string> = {
  supported: "Supported",
  partially_supported: "Partly supported",
  outdated: "Updated (original was outdated)",
  pending_simulation: "Simulation result",
};

export interface CheckStatus {
  claimId: number;
  verdict: LedgerVerdict;
  /** Verdict in words: "Supported", "Partly supported", "Updated (original was outdated)", "Simulation result". */
  verdictLabel: string;
  /** design.md 8.7 status: "Simulation result" | "Wording corrected" | "Checked against sources". */
  checkLabel: "Simulation result" | "Wording corrected" | "Checked against sources";
  changed: boolean;
  note: string | null;
  evidenceUrls: string[];
  /** Superseded wording. Show only behind "Show original wording". */
  before: string | null;
  checkedOn: string;
}

export function checkStatus(claimId: number): CheckStatus {
  const row = getClaim(claimId);
  const fc = factcheckRaw[String(claimId)];
  const changed = fc?.changed ?? false;
  const checkLabel =
    row.verdict === "pending_simulation" || row.simulated
      ? "Simulation result"
      : changed
        ? "Wording corrected"
        : "Checked against sources";
  return {
    claimId,
    verdict: row.verdict,
    verdictLabel: VERDICT_LABEL[row.verdict],
    checkLabel,
    changed,
    note: fc?.note ?? null,
    evidenceUrls: fc?.evidence_urls ?? [],
    before: fc?.before ?? null,
    checkedOn: factcheckMeta.checked_on,
  };
}

/** Ledger section filter labels, keyed by the site.json section id each row carries. */
export const LEDGER_SECTION_LABEL: Record<string, string> = {
  "cold-open": "Opening",
  "act-ethics": "Ethics",
  "act-law": "Law",
  "act-model": "Model",
  "act-public": "Public",
};

/**
 * Compact data the shared citation popover script reads (emitted once by
 * Layout.astro as <script type="application/json" id="cite-data">).
 */
export function citeData() {
  return {
    sim: SIM_SOURCE,
    simSentence: SIM_SENTENCE,
    sources: Object.fromEntries(
      Object.entries(sources).map(([id, s]) => [id, { n: sourceNumber(id), title: s.title, url: s.url, domain: sourceDomain(s.url) }]),
    ),
    claims: Object.fromEntries(
      ledger.map((r) => {
        const c = checkStatus(r.id);
        return [r.id, { verdict: c.verdictLabel, check: c.checkLabel }];
      }),
    ),
  };
}

