export type FeatureKey =
  | "topic_history"
  | "emotional_intensity"
  | "reactions"
  | "comment_rate"
  | "watch_completion"
  | "from_followed"
  | "hours_old";
export type Side = "her" | "design";

export interface FeedPost {
  rank: number;
  name: string;
  title: string;
  distress_related: boolean;
  score: number;
  features: Record<FeatureKey, number>;
}
export interface CfPost {
  rank: number;
  name: string;
  title: string;
  distress_related: boolean;
}
export interface Demo {
  feature_labels: Record<FeatureKey, string>;
  feature_side?: Record<FeatureKey, Side>;
  proxy_effect: { sensitive_share_overall_pct: number; sensitive_share_top_decile_pct: number };
  feed: FeedPost[];
  top_post: string;
  completeness: {
    shap_top_reason: FeatureKey;
    shap_top_reason_share_pct: number;
    three_reason_share_pct: number;
    platform_style_reason: string;
    platform_style_reason_share_pct: number;
    left_out_of_platform_reason_pct: number;
  };
  shap: { per_post: Record<string, Record<FeatureKey, number>>; base_value?: number };
  counterfactuals: {
    design_side: { new_feed: CfPost[]; top_decile_share_pct?: number; per_post?: Record<string, Record<FeatureKey, number>> };
    user_side?: { new_feed: CfPost[]; [k: string]: unknown };
  };
}

/** Raw demo data. Interactives may also import src/data/demo.json directly in their <script>. */
export const demo = demoRaw as unknown as Demo;

const DEFAULT_SIDE: Record<FeatureKey, Side> = {
  topic_history: "her",
  from_followed: "her",
  emotional_intensity: "design",
  reactions: "design",
  comment_rate: "design",
  watch_completion: "design",
  hours_old: "design",
};
/** Who controls each signal: "her" (teal) or "design" (rose). */
export const featureSide: Record<FeatureKey, Side> = { ...DEFAULT_SIDE, ...(demo.feature_side ?? {}) };
export const SIDE_LABEL: Record<Side, string> = { her: "About her", design: "About the post and the ranker" };
export const featureKeys = Object.keys(demo.feature_labels) as FeatureKey[];
export const featureLabels = demo.feature_labels;

function warnOrThrow(msg: string) {
  if (import.meta.env.DEV) throw new Error(msg);
  console.warn(`[content.ts] ${msg}`);
}

const sumShap = (name: string) => Object.values(demo.shap.per_post[name] ?? {}).reduce((a, b) => a + b, 0);

/**
 * The model's expected value. Uses demo.shap.base_value when the simulation
 * emits it; otherwise derived as score - sum(SHAP) for the top post.
 */
export const baseValue: number = (() => {
  const top = demo.feed.find((p) => p.name === demo.top_post) ?? demo.feed[0];
  const derived = top.score - sumShap(top.name);
  for (const p of demo.feed) {
    const b = p.score - sumShap(p.name);
    const ref = demo.shap.base_value ?? derived;
    if (Math.abs(b - ref) > 0.0015) warnOrThrow(`base value for ${p.name} is ${b.toFixed(4)}, expected ${ref.toFixed(4)}`);
  }
  return demo.shap.base_value ?? derived;
})();

export interface Attribution {
  feature: FeatureKey;
  label: string;
  side: Side;
  value: number;
}
export interface FeedPostView extends FeedPost {
  attributions: Attribution[]; // grouped by side (her first), then |value| desc
  sideTotals: Record<Side, number>;
  totalChange: number; // score - baseValue == sum of SHAP
}

function attributionsFor(name: string, shap = demo.shap.per_post): Attribution[] {
  const values = shap[name];
  if (!values) throw new Error(`content.ts: no SHAP values for ${name}`);
  const order: Side[] = ["her", "design"];
  return featureKeys
    .map((f) => ({ feature: f, label: featureLabels[f], side: featureSide[f], value: values[f] ?? 0 }))
    .sort((a, b) => order.indexOf(a.side) - order.indexOf(b.side) || Math.abs(b.value) - Math.abs(a.value));
}

/** The feed in rank order, with grouped, sorted attributions per post. */
export const feed: FeedPostView[] = [...demo.feed]
  .sort((a, b) => a.rank - b.rank)
  .map((p) => {
    const attributions = attributionsFor(p.name);
    const sideTotals = { her: 0, design: 0 } as Record<Side, number>;
    for (const a of attributions) sideTotals[a.side] += a.value;
    return { ...p, attributions, sideTotals, totalChange: sideTotals.her + sideTotals.design };
  });

/** Shared bar scale: the max |SHAP| across the whole feed (never changes between posts). */
export const shapScaleMax = Math.max(...feed.flatMap((p) => p.attributions.map((a) => Math.abs(a.value))));

/** Design-side counterfactual (retrained without one design signal). */
export const designCounterfactual = {
  removedSignal: simDisplay("cf_design_removed_signal"),
  newFeed: [...demo.counterfactuals.design_side.new_feed].sort((a, b) => a.rank - b.rank),
  /** Top-decile distress share after retraining. Falls back to the sim token until demo emits it. */
  topDecileSharePct:
    demo.counterfactuals.design_side.top_decile_share_pct ?? Number(simValue("distress_share_top_decile_no_intensity_pct")),
  /** Per-post SHAP for the retrained model, if the simulation emits it. */
  perPost: demo.counterfactuals.design_side.per_post ?? null,
  /** Names of the original top-N posts and whether they are unchanged after retraining. */
  topUnchanged(n: number) {
    const before = feed.slice(0, n).map((p) => p.name);
    const after = this.newFeed.slice(0, n).map((p) => p.name);
    return before.every((x, i) => x === after[i]);
  },
};
export const userCounterfactual = demo.counterfactuals.user_side ?? null;

export const proxyEffect = demo.proxy_effect;

/* ---- Told vs actual (completeness) ---- */

export interface Share {
  feature: FeatureKey;
  label: string;
  side: Side;
  value: number; // signed SHAP
  sharePct: number; // |value| / sum(|values|) * 100
}

/**
 * Shares of the top post's SHAP attributions. The simulation defines shares
 * over ABSOLUTE values (|v| / sum|v|): that reproduces
 * completeness.shap_top_reason_share_pct (37.5) and
 * platform_style_reason_share_pct (35.1). Negative contributions keep their
 * sign in `value` so the view can note them.
 */
export const topPostShares: Share[] = (() => {
  const top = feed.find((p) => p.name === demo.top_post) ?? feed[0];
  const total = top.attributions.reduce((a, x) => a + Math.abs(x.value), 0);
  const shares = top.attributions
    .map((a) => ({ feature: a.feature, label: a.label, side: a.side, value: a.value, sharePct: (Math.abs(a.value) / total) * 100 }))
    .sort((a, b) => b.sharePct - a.sharePct);
  const topReason = shares.find((s) => s.feature === demo.completeness.shap_top_reason);
  if (!topReason || Math.abs(topReason.sharePct - demo.completeness.shap_top_reason_share_pct) > 0.2)
    warnOrThrow(`top-reason share ${topReason?.sharePct.toFixed(2)} != completeness ${demo.completeness.shap_top_reason_share_pct}`);
  return shares;
})();

export const completeness = demo.completeness;
export const topPost = feed.find((p) => p.name === demo.top_post) ?? feed[0];

/* ------------------------------------------------------------------ */
/* Formatting helpers                                                  */
/* ------------------------------------------------------------------ */

/** Signed number with a real minus sign (U+2212): +0.225, −0.019 */
export function signed(n: number, digits = 3): string {
  const s = Math.abs(n).toFixed(digits);
  return (n < 0 ? "−" : "+") + s;
}
export const fixed = (n: number, digits = 3) => (n < 0 ? "−" : "") + Math.abs(n).toFixed(digits);
export const pct = (n: number, digits = 1) => `${n.toFixed(digits)}%`;
/** "16,300" -> 16300 */
export const parseCount = (n: string) => Number(n.replace(/[^0-9.]/g, ""));
